 static JObject MaterialsDiagnosticJson(SourceMaterialsDiagnostic sample){
  if(sample==null)return new JObject{["status"]="Unsupported",["reason"]="Actual diagnostic bank read fault, including managed OOM; no balance substitution",["banks"]=new JArray()};
  var rows=new JArray();foreach(var bank in sample.Banks)rows.Add(new JObject{["bank_entity"]=Key(bank.Bank),["faction"]=bank.Faction,["resource_kind"]="FactionTacticalMaterialsComponent.Current",["raw_component"]=Value(bank.Materials)});
  return new JObject{["status"]=sample.Status,["reason"]=sample.Reason,["banks"]=rows,["authority"]="Actual shared faction-bank component copies",["expected_faction_completeness_asserted"]=false};
 }
 static JArray QueueNetMaterialDeltas(SourceMaterialsDiagnostic before,SourceMaterialsDiagnostic after){
  var rows=new JArray();if(before==null||after==null)return rows;foreach(var prior in before.Banks)foreach(var current in after.Banks)if(prior.Bank==current.Bank&&prior.Faction==current.Faction)rows.Add(new JObject{["bank_entity"]=Key(prior.Bank),["faction"]=prior.Faction,["before"]=prior.Materials.Current,["after"]=current.Materials.Current,["observed_net_delta"]=(long)current.Materials.Current-prior.Materials.Current,["attribution"]="Unsupported: net during one queue call is not a charge/refund/income event"});return rows;
