 internal JObject Capture(){var em=world.Entities;uint version=em.ChangeVersion;long structural=em.StructuralVersion;var actors=new JArray();var healthByFaction=new Dictionary<int,long>();var countByFaction=new Dictionary<int,int>();var deadByFaction=new Dictionary<int,int>();var seen=new HashSet<string>();double nearest=double.PositiveInfinity,nearestAttacker=double.PositiveInfinity;Entity objective=em.GetComponentData<SkirmishMatchState>(world.Session).EnemyMainBase;bool positionKnown=em.Exists(objective)&&em.HasComponent<LocalTransform>(objective);var objectivePosition=positionKnown?em.GetComponentData<LocalTransform>(objective).Position:default;
 using var query=em.CreateEntityQuery(new EntityQueryDesc{All=new[]{ComponentType.ReadOnly<SkirmishAttemptOwnedComponent>()},Options=EntityQueryOptions.IncludeDisabledEntities|EntityQueryOptions.IgnoreComponentEnabledState});using var entities=query.ToEntityArray(Allocator.Temp);if(entities.Length>4096)throw new NotSupportedException("Validator attempt actor bound exceeded");
