 double? distance=null;if(positionKnown&&em.HasComponent<LocalTransform>(entity)){var at=em.GetComponentData<LocalTransform>(entity).Position;double dx=(double)at.x-objectivePosition.x,dz=(double)at.z-objectivePosition.z;distance=Math.Sqrt(dx*dx+dz*dz);if(faction==1&&!dead&&!em.HasComponent<Disabled>(entity)){nearest=Math.Min(nearest,distance.Value);if(em.HasComponent<UnitCombat>(entity)&&em.GetComponentData<UnitCombat>(entity).CanAttack!=0&&em.HasComponent<UnitAttack>(entity)&&em.GetComponentData<UnitAttack>(entity).Damage>0)nearestAttacker=Math.Min(nearestAttacker,distance.Value);}}JObject path=null;if(em.HasComponent<UnitPathRange>(entity)){var range=em.GetComponentData<UnitPathRange>(entity);int index=em.HasComponent<UnitPathFollow>(entity)?em.GetComponentData<UnitPathFollow>(entity).PathIndex:-1;path=new JObject{["range_start"]=range.Start,["range_length"]=range.Length,["follow_index"]=index};if(em.HasComponent<PathPoolComponent>(world.GridEntity)){var pool=em.GetComponentData<PathPoolComponent>(world.GridEntity).Cells;path["pool_live_length"]=pool.Length;if(range.Length>0){if(range.Start<0||(long)range.Start+range.Length>pool.Length)throw new InvalidOperationException("Validator observed invalid source path range");path["final_cell"]=Value(pool[range.Start+range.Length-1]);if(index>=0&&index<range.Length)path["next_cell"]=Value(pool[range.Start+index]);}}}actors.Add(new JObject{["path_state"]=path,["entity"]=id,["faction"]=faction,["dead_or_wreck"]=dead,["objective_distance"]=distance,["components"]=components,["capability_buffers"]=CapabilityBuffers(em,entity)});}
 bestFriendlyDistance=Math.Min(bestFriendlyDistance,nearest);bestAttackerDistance=Math.Min(bestAttackerDistance,nearestAttacker);var facts=new JObject();foreach(Type type in em.ComponentTypes(world.Session))if(typeof(IComponentData).IsAssignableFrom(type)&&(type.Name.Contains("Objective")||type.Name=="SkirmishMatchState"||type.Name.Contains("Capacity")||type.Name=="SkirmishExpandedSessionComponent"))facts[type.FullName]=Value(em.GetComponent(world.Session,type));var removed=new JArray(previousEntities.Where(e=>!seen.Contains(e)));previousEntities.Clear();foreach(string e in seen)previousEntities.Add(e);
